<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { Check, CopyDocument, Refresh, Warning } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { api, unwrap } from '../api/client'
import { useAuthStore } from '../stores/auth'
import MBStatusTag from '../components/MBStatusTag.vue'

const route=useRoute(); const auth=useAuthStore(); const loading=ref(true); const investigation=ref<any>(null)
const riskPinned=ref(false); const actionLoading=ref(''); let timer=0
const resultDialog=ref(false); const resultValue=ref('SUCCEEDED'); const resultTarget=ref<'payment'|'refund'>('payment'); const resultTargetId=ref<number|null>(null)
const refundDialog=ref(false); const refundYuan=ref(0.01)
const reversalDialog=ref(false); const reversalReason=ref('')
const payment=computed(()=>investigation.value?.payment); const channel=computed(()=>investigation.value?.channel)
const refunds=computed<any[]>(()=>investigation.value?.refunds||[])
const money=computed(()=>payment.value?formatMoney(payment.value.currency,payment.value.amountMinor):'—')
const reservedRefundMinor=computed(()=>refunds.value.filter(item=>['PENDING','UNKNOWN','SUCCEEDED'].includes(item.status)).reduce((sum,item)=>sum+item.amountMinor,0))
const availableRefundMinor=computed(()=>Math.max(0,(payment.value?.amountMinor||0)-reservedRefundMinor.value))
const blocked=computed(()=>['PENDING','UNKNOWN'].includes(payment.value?.status))
const canMarkResult=computed(()=>auth.profile?.platformAdmin&&blocked.value)
const canRefund=computed(()=>auth.hasPermission('PAYMENT_MANAGE')&&payment.value?.status==='SUCCEEDED'&&availableRefundMinor.value>0)
const canReverse=computed(()=>auth.profile?.platformAdmin&&payment.value?.status==='SUCCEEDED'&&reservedRefundMinor.value===0)
const date=(value?:string)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'
const hasNext=(index:string|number)=>Number(index)<(investigation.value?.timeline?.length||0)-1
const gateway=computed(()=>JSON.stringify(channel.value || { message:'数据库中没有渠道返回事实' },null,2))
function formatMoney(currency:string,value:number){return new Intl.NumberFormat('zh-CN',{style:'currency',currency}).format(value/100)}
async function load(){loading.value=true;try{investigation.value=unwrap(await api.get(`/tenant/payments/${route.params.id}/investigation`));refundYuan.value=Math.max(.01,availableRefundMinor.value/100)}finally{loading.value=false}}
async function runAction(name:string,request:()=>Promise<unknown>,success:string){if(actionLoading.value)return;actionLoading.value=name;try{await request();ElMessage.success(success);await load()}finally{actionLoading.value=''}}
async function queryChannel(){await runAction('query',()=>api.post(`/platform/payments/${route.params.id}/query-channel`),'渠道查询完成')}
function preparePaymentResult(){resultTarget.value='payment';resultTargetId.value=Number(route.params.id);resultValue.value='SUCCEEDED';resultDialog.value=true}
function prepareRefundResult(row:any){resultTarget.value='refund';resultTargetId.value=row.id;resultValue.value='SUCCEEDED';resultDialog.value=true}
async function markResult(){const path=resultTarget.value==='payment'?`/platform/payments/${resultTargetId.value}/simulate-result`:`/platform/refunds/${resultTargetId.value}/simulate-result`;await runAction('result',()=>api.post(path,{result:resultValue.value}),resultTarget.value==='payment'?'支付结果已更新':'退款结果已更新');resultDialog.value=false}
async function queryRefund(row:any){await runAction(`refund-query-${row.id}`,()=>api.post(`/platform/refunds/${row.id}/query-channel`),'退款渠道查询完成')}
async function requestRefund(){const amountMinor=Math.round(refundYuan.value*100);await runAction('refund',()=>api.post(`/tenant/payments/${route.params.id}/refunds`,{amountMinor},{headers:{'Idempotency-Key':crypto.randomUUID()}}),'退款请求已创建');refundDialog.value=false}
async function reversePayment(){await runAction('reversal',()=>api.post(`/platform/payments/${route.params.id}/reversal`,{reason:reversalReason.value.trim()}),'支付已冲正');reversalDialog.value=false;reversalReason.value=''}
async function copy(){await navigator.clipboard.writeText(gateway.value);ElMessage.success('渠道事实已复制')}
onMounted(()=>{load();timer=window.setTimeout(()=>riskPinned.value=true,4200)})
onBeforeUnmount(()=>window.clearTimeout(timer))
</script>

<template>
  <div v-loading="loading" class="investigation-page">
    <section class="investigation-head">
      <div><div class="breadcrumbs">财务中心　/　支付与退款　/　支付调查</div><div class="payment-title"><h1>PAY-{{ payment?.id || route.params.id }}</h1><MBStatusTag :status="payment?.status"/><span v-if="payment?.status==='UNKNOWN'" class="status-tag unknown">UNKNOWN</span></div><div v-if="payment" class="meta-row"><span>租户 <b>{{ auth.currentTenant?.tenantName }}</b></span><span>账单 <router-link class="link" :to="{path:'/finance/invoices',query:{keyword:payment.invoiceId}}">INV-{{ payment.invoiceId }}</router-link></span><span>金额 <b class="amount">{{ money }}</b></span><span>支付渠道 <b>{{ payment.channelCode }}</b></span><span>创建时间 <b>{{ date(payment.createdAt) }}</b></span></div></div>
      <div class="risk-slot"><div v-if="riskPinned && blocked" class="risk-card"><el-icon><Warning/></el-icon><div><strong>不可直接冲正</strong><p>当前交易状态为结果待确认，请先查询并确认渠道结果。</p></div></div></div>
    </section>
    <div class="investigation-grid">
      <section class="mb-card timeline-card"><header class="mb-card-title"><strong>支付调查时间线</strong><span class="status-tag success">● 实时数据</span></header><div class="timeline"><div v-for="(item,index) in investigation?.timeline || []" :key="`${item.occurredAt}-${index}`" class="timeline-row"><time>{{ date(item.occurredAt).split(' ')[1] }}</time><div class="timeline-node"><i :class="item.status?.toLowerCase()"/><span v-if="hasNext(index)"/></div><div class="timeline-copy"><strong>{{ item.title }}</strong><p>{{ item.description }}</p></div><div class="timeline-side"><MBStatusTag :status="item.status"/><small>{{ date(item.occurredAt) }}</small></div></div><el-empty v-if="!investigation?.timeline?.length" description="数据库中没有时间线事实"/></div></section>
      <div class="detail-stack"><section class="mb-card"><header class="mb-card-title"><strong>支付详情</strong></header><dl class="detail-list"><div><dt>支付单号</dt><dd>PAY-{{ payment?.id }}</dd></div><div><dt>外部交易号</dt><dd class="mono">{{ payment?.externalReference || '—' }}</dd></div><div><dt>状态</dt><dd><MBStatusTag :status="payment?.status"/></dd></div><div><dt>金额</dt><dd>{{ money }}</dd></div><div><dt>可退金额</dt><dd>{{ payment ? formatMoney(payment.currency,availableRefundMinor) : '—' }}</dd></div><div><dt>支付渠道</dt><dd>{{ payment?.channelCode || '—' }}</dd></div><div><dt>发起时间</dt><dd>{{ date(payment?.createdAt) }}</dd></div><div><dt>完成时间</dt><dd>{{ date(payment?.completedAt) }}</dd></div><div><dt>关联账单</dt><dd><router-link class="link" :to="{path:'/finance/invoices',query:{keyword:payment?.invoiceId}}">INV-{{ payment?.invoiceId }}</router-link></dd></div></dl></section><section class="mb-card gateway"><header class="mb-card-title"><strong>渠道返回事实（最近一次）</strong><el-button text :icon="CopyDocument" @click="copy">复制</el-button></header><pre>{{ gateway }}</pre></section></div>
      <section class="mb-card action-card"><header class="mb-card-title"><strong>调查与处理</strong></header><div class="action-list"><el-button :icon="Refresh" :loading="actionLoading==='query'" :disabled="!auth.profile?.platformAdmin||Boolean(actionLoading)" @click="queryChannel">再次查询支付渠道</el-button><el-button :icon="Check" :disabled="!canMarkResult||Boolean(actionLoading)" @click="preparePaymentResult">标记处理结果</el-button><el-button :disabled="!canRefund||Boolean(actionLoading)" @click="refundDialog=true">申请模拟退款</el-button><el-button type="danger" plain :disabled="!canReverse||Boolean(actionLoading)" @click="reversalDialog=true">执行冲正</el-button><el-button :icon="Check" @click="$router.push('/finance/reconciliation')">在对账中检查</el-button><el-alert v-if="blocked" title="结果未明确前不允许冲正" type="warning" :closable="false"/><p v-else-if="payment?.status==='SUCCEEDED'&&reservedRefundMinor>0" class="action-hint">存在已占用退款金额时不能冲正。</p></div></section>
    </div>
    <div class="lower-grid">
      <section class="mb-card table-card"><header class="mb-card-title"><strong>退款记录</strong><span>{{ refunds.length }} 条</span></header><el-table :data="refunds"><el-table-column label="退款单" width="92"><template #default="{row}">REF-{{ row.id }}</template></el-table-column><el-table-column prop="externalReference" label="外部交易号" min-width="150"/><el-table-column label="金额" width="105"><template #default="{row}">{{ formatMoney(row.currency,row.amountMinor) }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><MBStatusTag :status="row.status"/></template></el-table-column><el-table-column label="操作" min-width="150"><template #default="{row}"><el-button text type="primary" :loading="actionLoading===`refund-query-${row.id}`" :disabled="!auth.profile?.platformAdmin||Boolean(actionLoading)" @click="queryRefund(row)">查询</el-button><el-button text type="primary" :disabled="!auth.profile?.platformAdmin||!['PENDING','UNKNOWN'].includes(row.status)||Boolean(actionLoading)" @click="prepareRefundResult(row)">定结果</el-button></template></el-table-column></el-table><el-empty v-if="!refunds.length" description="当前付款没有退款记录" :image-size="58"/></section>
      <section class="mb-card table-card"><header class="mb-card-title"><strong>关联对账差异</strong><MBStatusTag :status="investigation?.differences?.length?'OPEN':'RESOLVED'"/></header><el-table :data="investigation?.differences || []"><el-table-column prop="id" label="差异ID"/><el-table-column prop="differenceType" label="差异类型"/><el-table-column prop="referenceId" label="关联对象"/><el-table-column label="状态"><template #default="{row}"><MBStatusTag :status="row.status"/></template></el-table-column></el-table><el-empty v-if="!investigation?.differences?.length" description="当前付款没有关联对账差异" :image-size="58"/></section>
      <section class="mb-card table-card"><header class="mb-card-title"><strong>关联失败任务</strong></header><el-table :data="investigation?.tasks || []"><el-table-column prop="id" label="任务ID"/><el-table-column prop="taskType" label="类型"/><el-table-column prop="attemptCount" label="重试"/><el-table-column prop="error" label="错误"/><el-table-column label="状态"><template #default="{row}"><MBStatusTag :status="row.status"/></template></el-table-column></el-table><el-empty v-if="!investigation?.tasks?.length" description="当前付款没有关联失败任务" :image-size="58"/></section>
    </div>
  </div>
  <div v-if="!riskPinned && blocked" class="risk-popup"><div class="risk-card floating"><el-icon><Warning/></el-icon><div><strong>不可直接冲正</strong><p>当前交易状态为结果待确认，请先查询并确认渠道结果。</p></div><button @click="riskPinned=true">收起</button></div></div>

  <el-dialog v-model="resultDialog" :title="resultTarget==='payment'?'确认支付渠道结果':'确认退款渠道结果'" width="430px"><p class="dialog-note">该操作会写入模拟渠道事实并推动{{ resultTarget==='payment'?'支付':'退款' }}状态收敛。</p><el-radio-group v-model="resultValue"><el-radio-button value="SUCCEEDED">成功</el-radio-button><el-radio-button value="FAILED">失败</el-radio-button><el-radio-button value="UNKNOWN">仍未知</el-radio-button></el-radio-group><template #footer><el-button @click="resultDialog=false">取消</el-button><el-button type="primary" :loading="actionLoading==='result'" @click="markResult">确认写入</el-button></template></el-dialog>
  <el-dialog v-model="refundDialog" title="申请模拟退款" width="430px"><p class="dialog-note">可退金额 {{ payment ? formatMoney(payment.currency,availableRefundMinor) : '—' }}。请求使用一次性幂等键提交。</p><el-form label-position="top"><el-form-item label="退款金额"><el-input-number v-model="refundYuan" :min="0.01" :max="availableRefundMinor/100" :precision="2" :step="1"/><span class="currency-unit">{{ payment?.currency }}</span></el-form-item></el-form><template #footer><el-button @click="refundDialog=false">取消</el-button><el-button type="primary" :loading="actionLoading==='refund'" :disabled="refundYuan<=0||refundYuan*100>availableRefundMinor" @click="requestRefund">确认退款</el-button></template></el-dialog>
  <el-dialog v-model="reversalDialog" title="确认整笔支付冲正" width="460px"><el-alert title="冲正会追加反向账务分录并恢复账单未付余额，操作不可撤回。" type="error" :closable="false"/><el-form label-position="top" class="dialog-form"><el-form-item label="冲正原因（必填）"><el-input v-model="reversalReason" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="说明核查结论和冲正原因"/></el-form-item></el-form><template #footer><el-button @click="reversalDialog=false">取消</el-button><el-button type="danger" :loading="actionLoading==='reversal'" :disabled="!reversalReason.trim()" @click="reversePayment">确认冲正</el-button></template></el-dialog>
</template>

<style scoped>
.investigation-head{min-height:114px;display:flex;justify-content:space-between;gap:24px}.breadcrumbs{font-size:12px;color:#6d7d9d;margin-bottom:14px}.payment-title{display:flex;align-items:center;gap:10px}.payment-title h1{margin:0 5px 0 0;font:700 28px/1 "Cascadia Mono",Consolas,monospace;color:#101938}.meta-row{display:flex;align-items:center;margin-top:16px;font-size:12px;color:#687899}.meta-row span{padding:0 14px;border-right:1px solid var(--mb-line)}.meta-row span:first-child{padding-left:0}.meta-row span:last-child{border:0}.meta-row b{margin-left:8px;color:#26395e}.meta-row .amount{color:#b56800}.risk-slot{width:349px;height:90px;flex:0 0 349px}.risk-card{width:349px;height:90px;border:1px solid #ffb8bd;border-radius:7px;background:#fff8f8;padding:17px;display:flex;gap:13px;color:#d6202e}.risk-card strong{display:block;font-size:15px;margin-bottom:7px;color:#8b1d29}.risk-card p{margin:0;color:#7d6d78;font-size:11px;line-height:1.55}.risk-card button{margin-left:auto;border:0;background:none;color:#9d5961;align-self:flex-start}.risk-popup{position:fixed;top:72px;right:18px;z-index:20}.risk-card.floating{box-shadow:0 12px 36px rgba(104,31,43,.18)}.investigation-grid{display:grid;grid-template-columns:minmax(520px,1.7fr) minmax(300px,.72fr) 200px;gap:12px}.timeline{padding:4px 18px}.timeline-row{min-height:68px;display:grid;grid-template-columns:92px 28px minmax(0,1fr) 145px;align-items:center}.timeline-row time{color:#667898;font:12px "Cascadia Mono",Consolas,monospace}.timeline-node{align-self:stretch;position:relative;display:flex;justify-content:center}.timeline-node i{width:13px;height:13px;border-radius:50%;margin-top:27px;z-index:1;box-shadow:0 0 0 3px #fff;background:#2675ec}.timeline-node i.succeeded,.timeline-node i.success{background:#12ab69}.timeline-node i.failed{background:#ef3340}.timeline-node i.unknown,.timeline-node i.pending{background:#f5a000}.timeline-node span{position:absolute;width:1px;background:#ccd7e5;top:35px;bottom:-35px}.timeline-copy{min-height:68px;padding:14px 8px;border-bottom:1px solid var(--mb-soft-line)}.timeline-copy strong{font-size:13px}.timeline-copy p{margin:5px 0 0;color:#697996;font-size:11px}.timeline-side{min-height:68px;padding:11px 0;text-align:right;border-bottom:1px solid var(--mb-soft-line);display:grid;justify-items:end;gap:5px}.timeline-side small{color:#7786a2}.detail-stack{display:grid;grid-template-rows:auto 190px;gap:12px}.detail-list{margin:0;padding:3px 13px 8px;font-size:11px}.detail-list>div{min-height:32px;display:grid;grid-template-columns:94px 1fr;align-items:center;border-bottom:1px solid var(--mb-soft-line)}.detail-list dt{color:#687898}.detail-list dd{margin:0;color:#2b3e61;overflow:hidden;text-overflow:ellipsis}.gateway pre{margin:10px 12px;padding:10px;background:#f7f9fc;border-radius:5px;color:#21447d;font:11px/1.45 "Cascadia Mono",Consolas,monospace;max-height:125px;overflow:auto}.action-list{display:grid;gap:9px;padding:12px}.action-list .el-button{margin:0;width:100%;justify-content:flex-start}.action-hint,.dialog-note{color:#6d7d98;font-size:12px;line-height:1.6}.lower-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:12px}.lower-grid .mb-card{min-height:220px}.dialog-form{margin-top:18px}.currency-unit{margin-left:10px;color:#6d7d98}
@media(min-width:1760px){.investigation-grid{grid-template-columns:minmax(680px,1.7fr) minmax(340px,.72fr) 230px}.timeline-row{min-height:76px}.lower-grid .mb-card{min-height:270px}}
@media(max-width:1320px){.investigation-grid{grid-template-columns:minmax(500px,1.6fr) minmax(300px,.8fr)}.action-card{grid-column:1/-1}.action-list{grid-template-columns:repeat(3,minmax(0,1fr))}.lower-grid{grid-template-columns:1fr}.risk-slot{display:none}.meta-row{flex-wrap:wrap;row-gap:8px}}
</style>
